lor--accent-1) 85%, transparent)"}}}}},"section-3":{"elements":{"button":{"color":{"background":"var(--wp--preset--color--contrast)","text":"var(--wp--preset--color--base)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--contrast) 85%, transparent)"}}}}},"section-5":{"elements":{"heading":{"color":{"text":"var(--wp--preset--color--base)"}},"button":{"color":{"background":"var(--wp--preset--color--accent-1)","text":"var(--wp--preset--color--contrast)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--accent-1) 85%, transparent)"}}},"link":{"color":{"text":"currentColor"}}}}}},"core/group":{"variations":{"section-4":{"elements":{"link":{"color":{"text":"currentColor"}},"button":{":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--accent-1) 85%, transparent)","text":"var(--wp--preset--color--contrast)"}},"color":{"background":"var(--wp--preset--color--accent-1)","text":"var(--wp--preset--color--contrast)"}},"heading":{"color":{"text":"currentColor"}}},"color":{"text":"var(--wp--preset--color--base)"}},"section-2":{"elements":{"button":{"color":{"background":"var(--wp--preset--color--accent-1)","text":"var(--wp--preset--color--contrast)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--accent-1) 85%, transparent)"}}}}},"section-3":{"elements":{"button":{"color":{"background":"var(--wp--preset--color--contrast)","text":"var(--wp--preset--color--base)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--contrast) 85%, transparent)"}}}}},"section-5":{"elements":{"heading":{"color":{"text":"var(--wp--preset--color--base)"}},"button":{"color":{"background":"var(--wp--preset--color--accent-1)","text":"var(--wp--preset--color--contrast)"},":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--accent-1) 85%, transparent)"}}},"link":{"color":{"text":"currentColor"}}}}}},"core/code":{"color":{"text":"var(--wp--preset--color--contrast)","background":"var(--wp--preset--color--accent-5)"}},"core/paragraph":{"elements":{"link":{"color":{"text":"var(--wp--preset--color--contrast)"}}}},"core/post-author-name":{"elements":{"link":{"color":{"text":"var(--wp--preset--color--contrast)"}}}},"core/post-title":{"elements":{"link":{"color":{"text":"var(--wp--preset--color--contrast)"}}}},"core/pullquote":{"color":{"text":"var(--wp--preset--color--contrast)"},"elements":{"cite":{"color":{"text":"var(--wp--preset--color--accent-4)"}}}},"core/quote":{"elements":{"cite":{"color":{"text":"var(--wp--preset--color--accent-4)"}}}},"core/post-terms":{"variations":{"post-terms-1":{"elements":{"link":{"color":{"background":"var(--wp--preset--color--accent-5)"},"border":{"color":"var(--wp--preset--color--accent-5)"}}}}}}},"elements":{"button":{":hover":{"color":{"background":"color-mix(in srgb, var(--wp--preset--color--accent-1) 85%, transparent)","text":"var(--wp--preset--color--contrast)"}},"color":{"text":"var(--wp--preset--color--custom-t-o)","background":"var(--wp--preset--color--custom-kolor-marki)"}},"link":{"color":{"text":"var(--wp--preset--color--custom-kolor-marki)"},":hover":{"color":{"text":"var(--wp--preset--color--custom-akcent)"}}},"heading":{"color":{"text":"var(--wp--preset--color--custom-tekst)"}}},"color":{"text":"var(--wp--preset--color--custom-tekst)","background":"var(--wp--preset--color--custom-t-o)"},"typography":{"lineHeight":"1.4","fontSize":"1.13rem"},"css":"/* Dodatkowy CSS (Additional CSS) - dostępność i responsywność */

/* WCAG 2.4.7: widoczny fokus - nigdy samo outline: none */
:where(a, button, input, select, textarea, summary):focus-visible {
 outline: 3px solid var(--wp--preset--color--contrast, #1E1A17);
 outline-offset: 3px;
}

/* WCAG 2.4.11: element z fokusem nie może chować się pod przyklejonym nagłówkiem */
html {
 scroll-padding-top: 5rem;
}

/* WCAG 2.5.8: cel dotykowy min. 24 x 24 px */
.wp-block-navigation-item__content,
.wp-block-social-link a {
 min-height: 24px;
 min-width: 24px;
 padding-block: 0.5rem;
}

/* Płynna typografia zamiast wielu breakpointów */
h1 {
 font-size: clamp(1.75rem, 1.2rem + 2.5vw, 3rem);
}

/* Mobile first: kolumny jedna pod drugą z odstępami na wąskich ekranach */
@media (max-width: 600px) {
 .wp-block-columns {
 gap: 1.25rem;
 }
 .wp-block-columns .wp-block-column {
 margin-bottom: 1.25rem;
 }
 .wp-block-cover {
 min-height: 45vh;
 padding-inline: 1rem;
 }
}
/* WCAG 1.4.3: ciemny kolor bazowy pod zdjęciem Cover dla białego tekstu */
.wp-block-cover {
 background-color: #1E1A17 !important;
}"},"settings":{"color":{"palette":{"theme":[{"color":"#DFDCD7","name":"Base","slug":"base"},{"color":"#191919","name":"Contrast","slug":"contrast"},{"color":"#7A9BDB","name":"Accent 1","slug":"accent-1"},{"color":"#F7E6FF","name":"Accent 2","slug":"accent-2"},{"color":"#182949","name":"Accent 3","slug":"accent-3"},{"color":"#5F5F5F","name":"Accent 4","slug":"accent-4"},{"color":"#D7D3CC","name":"Accent 5","slug":"accent-5"},{"color":"#19191933","name":"Accent 6","slug":"accent-6"}],"custom":[{"color":"#faf7f2","name":"Tło","slug":"custom-t-o"},{"color":"#1e1a17","name":"Tekst","slug":"custom-tekst"},{"color":"#5c3a21","name":"Kolor Marki","slug":"custom-kolor-marki"},{"color":"#8c4a27","name":"Akcent","slug":"custom-akcent"}]}},"typography":{"fontSizes":{"custom":[{"name":"New Font Size 1","size":"16px","slug":"custom-1"}]}}},"isGlobalStylesUserThemeJSON":true,"version":3}
